package com.nihilent.condition_statement;

public class Petrolisfilled {

	// data type Boolean---> true or false

	boolean ispetrolempty;

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		Petrolisfilled petrolisfilled = new Petrolisfilled();
		if (petrolisfilled.ispetrolempty) {
			System.out.println("Petrol is empty");

		} else {
			System.out.println("Start the bike");
		}

	}

}
